ALTER TABLE public.staff_reimbursements ADD COLUMN IF NOT EXISTS approval_status text NOT NULL DEFAULT 'approved', ADD COLUMN IF NOT EXISTS approved_by uuid, ADD COLUMN IF NOT EXISTS approved_at timestamptz, ADD COLUMN IF NOT EXISTS receipt_hash text, ADD COLUMN IF NOT EXISTS review_reasons jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS payout_method text;
CREATE OR REPLACE FUNCTION public.approve_staff_expense_claim(p_claim uuid,p_payout text) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE c public.staff_reimbursements%ROWTYPE; debit_account uuid; payable uuid; j uuid; BEGIN SELECT * INTO c FROM public.staff_reimbursements WHERE id=p_claim FOR UPDATE; IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),c.tenant_id) THEN RAISE EXCEPTION 'Claim not available'; END IF; IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager approval required'; END IF; IF c.amount>300 AND NOT public.people_owner(c.tenant_id,auth.uid()) THEN RAISE EXCEPTION 'Owner approval required over HK$300'; END IF; IF p_payout NOT IN('bank','payroll','petty_cash') THEN RAISE EXCEPTION 'Choose a payment method'; END IF; IF c.approval_status='approved' THEN RETURN c.journal_entry_id; END IF; IF c.status='paid' THEN RAISE EXCEPTION 'Claim already paid'; END IF; SELECT gl_account_id INTO debit_account FROM public.petty_cash_classifications WHERE id=c.category_id AND tenant_id=c.tenant_id; IF debit_account IS NULL THEN RAISE EXCEPTION 'Pick an account for this category'; END IF; SELECT id INTO payable FROM public.chart_of_accounts WHERE tenant_id=c.tenant_id AND name='Staff Reimbursements Payable' ORDER BY code LIMIT 1; IF payable IS NULL THEN RAISE EXCEPTION 'Staff Reimbursements Payable account is missing'; END IF; INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,status,posted_at,created_by) VALUES(c.tenant_id,c.claim_date,'Staff reimbursement — '||c.claimant_name||' — '||c.description,'staff_reimbursement',c.id,'posted',now(),auth.uid()) RETURNING id INTO j; INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,line_no,memo) VALUES(c.tenant_id,j,debit_account,c.amount,0,1,c.description),(c.tenant_id,j,payable,0,c.amount,2,'Owed to '||c.claimant_name); UPDATE public.staff_reimbursements SET approval_status='approved',approved_by=auth.uid(),approved_at=now(),journal_entry_id=j,payout_method=p_payout WHERE id=c.id; INSERT INTO public.audit_log(tenant_id,user_id,action,table_name,record_id,new_data) VALUES(c.tenant_id,auth.uid(),'approve_staff_claim','staff_reimbursements',c.id,jsonb_build_object('journal_entry_id',j,'amount',c.amount,'payout',p_payout)); RETURN j; END $$;
GRANT EXECUTE ON FUNCTION public.approve_staff_expense_claim(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.staff_claim_review_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.approval_status<>'pending_review' THEN RAISE EXCEPTION 'New claims require review'; END IF; ELSIF NEW.approval_status='approved' AND OLD.approval_status IS DISTINCT FROM 'approved' THEN IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) OR (NEW.amount>300 AND NOT public.people_owner(NEW.tenant_id,auth.uid())) OR NEW.approved_by IS DISTINCT FROM auth.uid() OR NEW.journal_entry_id IS NULL THEN RAISE EXCEPTION 'Claim requires authorised approval and booking'; END IF; ELSIF NEW.status='paid' AND OLD.approval_status<>'approved' THEN RAISE EXCEPTION 'Approve the claim before paying'; END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_claim_review_guard BEFORE INSERT OR UPDATE ON public.staff_reimbursements FOR EACH ROW EXECUTE FUNCTION public.staff_claim_review_guard();